SELECT DISTINCT ?length ?n0 ?e1 ?n1 WHERE {
{ {
SELECT DISTINCT ?source ?target ?n0 ?n1 ?e1 WHERE {
  ?e1 <http://www.w3.org/1999/02/22-rdf-syntax-ns#type> <https://xgap.test/toy/Edge> .
  ?e1 <https://xgap.test/toy/source> ?n0 .
  ?e1 <https://xgap.test/toy/target> ?n1 .
  ?e1 <https://xgap.test/toy/label> "KNOWS" .
  ?n0 <https://xgap.test/toy/id> ?v0 .
  FILTER(?v0 = "a")
  BIND(?n0 AS ?source)
  BIND(?n1 AS ?target)
}
}
BIND(1 AS ?length)
}
}

SELECT DISTINCT ?entity ?age WHERE { {
SELECT DISTINCT ?source ?target ?n0 WHERE {
  { ?n0 ?_p0 ?_o0 . }
  UNION
  { ?_s0 ?_p1 ?n0 . }
  ?n0 a <https://xgap.test/toy/Person> .
  BIND(?n0 AS ?source)
  BIND(?n0 AS ?target)
}
}
?source a ?nodeDomain . VALUES ?nodeDomain { <https://xgap.test/toy/Person> }
BIND(?source AS ?entity)
OPTIONAL { ?source <https://xgap.test/toy/age> ?age . }
}

